"use server";

import { prisma } from "@/src/lib/prisma";
import { revalidatePath } from "next/cache";

// YENİ KAYIT OLUŞTURMA
export async function createNewTask(title: string, content: string) {
  try {
    // Veritabanındaki ilk kullanıcıyı al (veya session'dan çek)
    const user = await prisma.user.findFirst();

    if (!user) {
      return { success: false, error: "Geen gebruiker gevonden." };
    }

    // JSON içeriğinden sprint bilgisini çekmeye çalışalım
    let sprintValue = "1";
    try {
      const parsed = JSON.parse(content);
      // Eğer modal'da sprintNr kullanıyorsak o başlığa zaten ekleniyor 
      // ama veritabanı alanı için de ayrıştıralım
    } catch (e) {}

    await prisma.task.create({
      data: {
        title,
        description: "", // Gerekirse burayı da doldurabilirsin
        content,        // Şablon verileri burada JSON olarak saklanıyor
        status: "TODO",
        priority: "MEDIUM",
        userId: user.id,
      },
    });

    revalidatePath("/tasks");
    revalidatePath("/");
    return { success: true };
  } catch (error) {
    console.error("Task Create Error:", error);
    return { success: false, error: "Fout bij opslaan." };
  }
}

// GÜNCELLEME (BEWERKEN)
export async function updateTask(id: string, data: { title: string; content: string; sprint?: string }) {
  try {
    await prisma.task.update({
      where: { id },
      data: {
        title: data.title,
        content: data.content,
        // sprint alanı modelinde varsa:
        // sprint: data.sprint 
      },
    });

    revalidatePath("/tasks");
    revalidatePath("/");
    return { success: true };
  } catch (error) {
    console.error("Task Update Error:", error);
    return { success: false, error: "Fout bij updaten." };
  }
}

// SİLME (VERWIJDEREN)
export async function deleteTask(id: string) {
  try {
    await prisma.task.delete({
      where: { id },
    });

    revalidatePath("/tasks");
    revalidatePath("/");
    return { success: true };
  } catch (error) {
    console.error("Task Delete Error:", error);
    return { success: false, error: "Fout bij verwijderen." };
  }
}