"use client";

import { useState, useEffect } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Button } from "@/components/ui/button";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { createNewTask, updateTask } from "@/app/actions/task-actions";
import { Loader2 } from "lucide-react";

const SCRUM_TEMPLATES = {
  DAILY_SCRUM: {
    title: "Daily Scrum",
    fields: ["Wat is klaar sinds vorige Daily Scrum?", "Werkt het team volgens planning?", "Zijn er problemen / obstakels?"]
  },
  SPRINT_PLANNING: {
    title: "Sprint Planning",
    fields: ["Sprint Backlog (Grote stappen)", "To Do lijst (Concrete activiteiten)", "Sprint oplevering", "Definition of Done"]
  },
  RETROSPECTIVE: {
    title: "Sprint Retrospective",
    fields: ["Wat ging allemaal goed?", "Wat kan beter?", "Actiepunt voor volgende Sprint"]
  },
  REVIEW: {
    title: "Sprint Review",
    fields: ["Wat heb jij gemaakt/geleerd?", "Wat beheers jij nog niet voldoende?", "Hoe ga jij dit verhelpen?"]
  }
};

export default function TaskFormModal({ open, setOpen, initialData }: any) {
  const [selectedTemplate, setSelectedTemplate] = useState<string>("");
  const [formData, setFormData] = useState<any>({});
  const [sprintNr, setSprintNr] = useState("1");
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if (initialData) {
      setSprintNr(initialData.sprint || "1");
      try {
        const parsed = JSON.parse(initialData.content);
        setFormData(parsed.templateData || {});
        // Başlığa göre template'i tahmin et
        if (initialData.title.includes("Daily")) setSelectedTemplate("DAILY_SCRUM");
        else if (initialData.title.includes("Planning")) setSelectedTemplate("SPRINT_PLANNING");
        else if (initialData.title.includes("Retro")) setSelectedTemplate("RETROSPECTIVE");
        else if (initialData.title.includes("Review")) setSelectedTemplate("REVIEW");
      } catch(e) { setFormData({}); }
    } else {
      setFormData({});
      setSelectedTemplate("");
      setSprintNr("1");
    }
  }, [initialData, open]);

  const handleSave = async () => {
    setLoading(true);
    const contentString = JSON.stringify({ team: "WorkSpace", templateData: formData });
    const title = `${SCRUM_TEMPLATES[selectedTemplate as keyof typeof SCRUM_TEMPLATES]?.title || "Document"} - Sprint ${sprintNr}`;

    if (initialData) {
      await updateTask(initialData.id, { title, content: contentString, sprint: sprintNr });
    } else {
      await createNewTask(title, contentString);
    }
    
    setOpen(false);
    setLoading(false);
  };

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogContent className="bg-[#0E153A]/98 border border-teal-400/30 text-white max-w-3xl overflow-y-auto max-h-[90vh] rounded-[2.5rem] shadow-2xl backdrop-blur-2xl">
        <DialogHeader>
          <DialogTitle className="text-3xl font-black bg-gradient-to-r from-teal-300 to-fuchsia-400 bg-clip-text text-transparent uppercase tracking-tight">
            {initialData ? "Document Bewerken" : "Nieuw Document"}
          </DialogTitle>
        </DialogHeader>

        <div className="space-y-6 mt-6">
          <div className="grid grid-cols-2 gap-6">
            <div className="space-y-2">
              <label className="text-[10px] text-teal-400 font-black uppercase tracking-[0.2em] ml-1">Template Selectie</label>
              <Select value={selectedTemplate} onValueChange={(val) => setSelectedTemplate(val)}>
                <SelectTrigger className="bg-black/40 border-teal-400/20 h-14 rounded-2xl focus:ring-fuchsia-500">
                  <SelectValue placeholder="Kies een template" />
                </SelectTrigger>
                <SelectContent className="bg-[#0E153A] border-teal-400/30 text-white rounded-xl">
                  {Object.entries(SCRUM_TEMPLATES).map(([key, value]) => (
                    <SelectItem key={key} value={key} className="focus:bg-teal-400/10 focus:text-teal-300">{value.title}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <label className="text-[10px] text-teal-400 font-black uppercase tracking-[0.2em] ml-1">Sprint Nummer</label>
              <Input type="number" value={sprintNr} onChange={(e) => setSprintNr(e.target.value)} className="bg-black/40 border-teal-400/20 h-14 rounded-2xl" />
            </div>
          </div>

          {selectedTemplate && (
            <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-500">
              <div className="p-4 rounded-2xl bg-gradient-to-r from-teal-400/10 to-transparent border border-teal-400/10">
                <p className="text-[10px] text-teal-300 font-bold tracking-widest uppercase italic">Project: WorkSpace | Klas: 2024-ST-ST-L-NEXT-2</p>
              </div>
              
              {SCRUM_TEMPLATES[selectedTemplate as keyof typeof SCRUM_TEMPLATES].fields.map((field) => (
                <div key={field} className="space-y-2">
                  <label className="text-xs font-black text-teal-100/60 uppercase tracking-wider ml-1">{field}</label>
                  <Textarea 
                    value={formData[field] || ""}
                    placeholder="Details invoeren..."
                    className="bg-black/40 border-teal-400/20 min-h-[120px] rounded-2xl focus:border-fuchsia-400 transition-all text-teal-50"
                    onChange={(e) => setFormData({...formData, [field]: e.target.value})}
                  />
                </div>
              ))}
            </div>
          )}

          <Button 
            onClick={handleSave} 
            disabled={!selectedTemplate || loading}
            className="w-full bg-gradient-to-r from-teal-400 to-fuchsia-400 text-[#070B24] font-black h-16 rounded-2xl shadow-[0_0_20px_rgba(45,212,191,0.2)] hover:scale-[1.02] active:scale-95 transition-all text-lg"
          >
            {loading ? <Loader2 className="animate-spin" /> : "DOCUMENT OPSLAAN"}
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  );
}